const key='chakra-studio-os-v1';let db;try{db=JSON.parse(localStorage.getItem(key))||structuredClone(seed);if(!validDB(db))throw Error()}catch{db=structuredClone(seed)}
function validDB(v){return v&&v.version===1&&v.settings&&typeof v.settings.owner==='string'&&typeof v.settings.currency==='string'&&['projects','tasks','clients','subscriptions','meetings','transactions','users','invoices','activity'].every(k=>Array.isArray(v[k]))&&v.projects.every(p=>p.id&&typeof p.name==='string')&&v.tasks.every(t=>t.id&&typeof t.title==='string')&&v.invoices.every(i=>Array.isArray(i.items)&&i.items.every(x=>Number.isFinite(+x.qty)&&Number.isFinite(+x.rate)))&&v.subscriptions.every(s=>Number.isFinite(+s.amount))&&v.transactions.every(t=>Number.isFinite(+t.amount))}
let page=location.hash.slice(1)||'home', filter=page==='projects'?'Active':'All',query='',clientSelected=db.clients[0]?.id,invoice=structuredClone(db.invoices[0]),settingsTab='Studio identity',financePeriod='Quarter';const pages=['Home','Projects','Tasks','Clients','Finance','Subscriptions','Bills','Insights','Users','Settings'];
function money(v,currency=db.settings.currency){return new Intl.NumberFormat('en-US',{style:'currency',currency,maximumFractionDigits:Math.abs(v)%1?2:0}).format(v||0)}
function localSave(message){try{localStorage.setItem(key,JSON.stringify(db));if(message){db.activity.unshift({text:message,date:new Date().toISOString()});db.activity=db.activity.slice(0,35);localStorage.setItem(key,JSON.stringify(db));toast(message)}return true}catch{toast('Storage is full or unavailable. Export a backup before leaving.');return false}}
function toast(msg){window.studioMotion?.run($('#toast'),{opacity:[0,1]},.15,typeof db==='undefined'?'System':db.settings.motion);$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
function go(p){if(p===page){render();return}location.hash=p}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'home';filter=page==='projects'?'Active':'All';query='';render()});
function badge(v){const color=/Done|Delivered|Active|Paid|Completed|On track/.test(v)?'green':/Hold|High|Overdue|Blacklisted/.test(v)?'red':/Review/.test(v)?'purple':/Low|Planning|Upcoming/.test(v)?'blue':'gray';return `<span class="badge ${color}">${esc(v)}</span>`}
function legacyAvatar(name='Mineth',i=0){return `<span class="avatar" title="${esc(name)}" style="background:linear-gradient(140deg,${['#a56c48,#493941','#557c73,#303c40','#8b6678,#413650'][i%3]})">${esc(initials(name))}</span>`}
