function progress(v){v=Math.min(100,Math.max(0,+v||0));return `<div class="progress"><span style="width:${v}%"></span></div>`}
function stat(title,value,ico,color='orange',note=''){return `<div class="stat"><div class="stat-head"><span class="tile ${color}">${icon(ico)}</span><div><small>${esc(title)}</small><strong>${esc(value)}</strong></div></div>${note?`<div class="stat-footer">${esc(note)}</div>`:''}</div>`}
function panel(title,ico,body,action='',sub=''){return `<section class="panel"><div class="panel-head"><div class="panel-title"><span class="tile">${icon(ico)}</span><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div></div>${action}</div>${body}</section>`}
const navbutton=(title,p)=>`<button data-go="${p}">${title} ${icon('arrow')}</button>`;
function hero(title,sub,button=''){return heading(title,sub,button)}
function heading(title,sub,action=''){return `<div class="page-head"><div><h1>${title}</h1><div class="muted">${sub}</div></div>${action}</div>`}
const addBtn=(kind,label)=>`<button class="primary" data-add="${kind}">${icon('plus')}${label}</button>`;
const revenue=()=>db.transactions.filter(t=>t.type==='Income').reduce((a,t)=>a+Number(t.amount),0),expenses=()=>db.transactions.filter(t=>t.type==='Expense').reduce((a,t)=>a+Number(t.amount),0),totalInvoice=i=>i.items.reduce((s,x)=>s+(+x.qty)*(+x.rate),0)*(1+(+i.tax||0)/100),outstanding=()=>db.invoices.filter(i=>i.status==='Sent'||i.status==='Overdue').reduce((a,i)=>a+totalInvoice(i),0);
function taskRows(){return db.tasks.filter(t=>t.status!=='Done').sort((a,b)=>(a.priority==='High'?-1:0)-(b.priority==='High'?-1:0)||a.due.localeCompare(b.due)).slice(0,5).map(t=>`<div class="row"><span class="monogram">${icon('tasks')}</span><div class="row-main"><b>${esc(t.title)}</b><small>${esc(db.projects.find(p=>p.id===t.project)?.name||'Studio')}</small></div><div style="width:50px">${progress(t.progress)}</div><button class="iconbtn" data-edit="tasks:${t.id}" aria-label="Edit ${esc(t.title)}">${icon('chevron')}</button></div>`).join('')||'<div class="empty">All caught up.</div>'}
function home(){const open=db.projects.filter(isOpenProject),attention=open.filter(p=>p.due<today()||p.status==='On Hold');return heading('Studio overview',attention.length?attention.length+' projects need attention':'Your projects, priorities and finances.',addBtn('projects','New project'))+`<div class="stats">${stat('Revenue',money(revenue()),'money','green','All recorded transactions')}${stat('Net profit',money(revenue()-expenses()),'chart','gray','All recorded transactions')}${stat('Outstanding',money(outstanding()),'clock','red','Sent and overdue invoices')}${stat('Open projects',open.length,'layers','blue','Includes On Hold')}</div><div class="grid home-grid">${panel('Project attention','projects',attention.map(p=>`<div class="row"><div class="row-main"><b>${esc(p.name)}</b><small>${esc(p.client)} · Due ${date(p.due)}</small></div>${badge(p.status)}<button data-edit="projects:${esc(p.id)}">Open</button></div>`).join('')||'<div class="empty">No projects need attention.</div>',navbutton('All projects','projects'))}${panel('Priority tasks','tasks',taskRows(),navbutton('All tasks','tasks'))}</div><div class="grid home-finance">${panel('Cashflow','chart',chart(),rangeControl())}${panel('Recent activity','clock',db.activity.slice(0,4).map(a=>`<div class="row"><div class="row-main"><b>${esc(a.text)}</b><small>${date(a.date)}</small></div></div>`).join('')||'<div class="empty">No recent activity.</div>')}</div>`}
function projectRows(list){return list.map(p=>`<tr><td><div class="project-name"><span class="monogram">${esc(initials(p.name))}</span>${esc(p.name)}</div></td><td>${esc(p.client)}</td><td>${badge(p.status)}</td><td><div class="progress-cell">${p.progress}% ${progress(p.progress)}</div></td><td>${date(p.due)}</td><td>${avatars()}</td><td><button class="iconbtn" data-edit="projects:${p.id}" aria-label="Edit ${esc(p.name)}">${icon('edit')}</button></td></tr>`).join('')}
function search(placeholder){return `<div class="searchbox">${icon('search')}<input id="page-search" placeholder="${placeholder}" value="${esc(query)}" aria-label="${placeholder}"></div>`}
function tasks(){let list=db.tasks.filter(t=>(filter==='All'||filter==='Mine'&&isMyTask(t)||filter==='Overdue'&&t.due<today()&&t.status!=='Done'||filter==='Done'&&t.status==='Done')&&(!query||t.title.toLowerCase().includes(query.toLowerCase())));return hero('Tasks','Manage studio execution across projects.',addBtn('tasks','New Task'))+`<div class="toolbar"><div class="tabs">${['All','Mine','Overdue','Done'].map(x=>`<button data-filter="${x}" class="${filter===x?'selected':''}">${x}</button>`).join('')}</div>${search('Find a task...')}</div><div class="stats">${stat('Total Tasks',db.tasks.length,'chart')}${stat('Due Today',db.tasks.filter(t=>t.due===today()&&t.status!=='Done').length,'clock','red')}${stat('In Progress',db.tasks.filter(t=>t.status==='In Progress').length,'clock','blue')}${stat('Completed',db.tasks.filter(t=>t.status==='Done').length,'tasks','green')}</div><div class="kanban">${['Backlog','In Progress','Review','Done'].map(status=>`<section class="column" data-drop="${status}"><div class="column-head"><span>${status} <small>(${list.filter(t=>t.status===status).length})</small></span><button data-add="tasks" data-status="${status}" aria-label="Add task to ${status}">${icon('plus')}</button></div>${list.filter(t=>t.status===status).map(t=>`<article class="task-card" draggable="true" data-task="${t.id}"><div class="task-top"><h3>${esc(t.title)}</h3>${badge(t.priority)}</div><div class="section-note">${esc(db.projects.find(p=>p.id===t.project)?.name||'Studio')}</div><p>${esc(t.description==='Keep the next step clear and move the project forward.'?'':t.description)}</p><div class="progress-cell"><small>${t.progress}%</small>${progress(t.progress)}</div><div class="task-bottom"><span>${date(t.due)}</span>${avatar(t.assignee)}</div><div class="task-bottom"><select aria-label="Status for ${esc(t.title)}" data-task-status="${t.id}">${options(['Backlog','In Progress','Review','Done'],t.status)}</select><button class="iconbtn" data-edit="tasks:${t.id}" aria-label="Edit ${esc(t.title)}">${icon('edit')}</button></div></article>`).join('')||'<div class="empty">Drop tasks here</div>'}</section>`).join('')}</div><p class="section-note">Drag cards between columns, or use each card’s status menu.</p>`}
function clients(){const list=db.clients.filter(c=>(filter==='All'||c.status===filter)&&(!query||(c.name+c.contact+c.email).toLowerCase().includes(query.toLowerCase())));const c=list.find(x=>x.id===clientSelected)||list[0];return hero('Clients','Strong relationships. Exceptional work.',addBtn('clients','Add Client'))+`<div class="stats">${stat('Total Clients',db.clients.length,'clients')}${stat('Active Clients',db.clients.filter(c=>c.status==='Active').length,'users','green')}${stat('Inactive',db.clients.filter(c=>c.status==='Inactive').length,'clock','blue')}${stat('Outstanding Receivables',money(outstanding()),'money')}</div><div class="toolbar"><div class="tabs">${['All','Active','Inactive','Blacklisted'].map(x=>`<button data-filter="${x}" class="${filter===x?'selected':''}">${x}</button>`).join('')}</div>${search('Search clients by name or contact...')}</div><div class="client-layout"><div class="table-wrap"><table><thead><tr><th>Client</th><th>Contact</th><th>Projects</th><th>Status</th><th></th></tr></thead><tbody>${list.map(x=>`<tr class="clickable ${c?.id===x.id?'selected-row':''}" data-client="${x.id}" tabindex="0" role="button" aria-label="Select ${esc(x.name)}"><td><div class="project-name"><span class="monogram">${esc(initials(x.name))}</span><div>${esc(x.name)}<span class="sub">${esc(x.email)}</span></div></div></td><td>${esc(x.contact)}</td><td>${db.projects.filter(p=>p.client===x.name).length}</td><td>${badge(x.status)}</td><td>${icon('chevron')}</td></tr>`).join('')}</tbody></table>${!list.length?'<div class="empty">No matching clients</div>':''}</div>${c?`<section class="panel detail"><div class="detail-head"><span class="monogram">${esc(initials(c.name))}</span><div><strong>${esc(c.name)}</strong><p class="section-note">${esc(c.website)}</p></div>${badge(c.status)}</div><dl><dt>Primary Contact</dt><dd>${esc(c.contact)}</dd><dt>Email</dt><dd><a href="mailto:${esc(c.email)}">${esc(c.email)}</a></dd><dt>Phone</dt><dd>${esc(c.phone)||'Not provided'}</dd><dt>Industry</dt><dd>${esc(c.industry)}</dd><dt>Location</dt><dd>${esc(c.location)}</dd></dl><h3 style="font-size:13px">Notes</h3><p class="section-note">${esc(c.notes)||'Add notes about your relationship and next steps.'}</p><div class="mini-stats"><div><strong>${db.projects.filter(p=>p.client===c.name).length}</strong><small>Projects</small></div><div style="grid-column:span 2"><strong>${money(db.invoices.filter(i=>i.client===c.name&&['Sent','Overdue'].includes(i.status)).reduce((s,i)=>s+totalInvoice(i),0))}</strong><small>Outstanding</small></div></div><button class="primary wide" style="margin-top:22px" data-edit="clients:${c.id}">Edit Client ${icon('arrow')}</button></section>`:''}</div>`}
function subscriptions(){const active=db.subscriptions.filter(s=>s.status==='Active'),monthly=active.reduce((s,x)=>s+ +x.amount,0),list=db.subscriptions.filter(s=>(filter==='All'||s.status===filter)&&s.name.toLowerCase().includes(query.toLowerCase()));return hero('Subscriptions','Manage recurring tools, renewals, FX rates, and reminders.',addBtn('subscriptions','Add Subscription'))+`<div class="stats">${stat('Monthly Recurring',money(monthly,'USD'),'finance','green','≈ '+money(monthly*db.settings.fx,'LKR'))}${stat('Annualized',money(monthly*12,'USD'),'chart','orange','12 × monthly cost')}${stat('Active Subscriptions',active.length,'layers','blue')}${stat('Renewing in 7 days',active.filter(s=>s.renewal>=today()&&s.renewal<=offset(7)).length,'bell','red')}</div><div class="toolbar"><h3>All Subscriptions (${list.length})</h3>${search('Search subscriptions...')}<select id="status-filter" aria-label="Subscription status">${options(['All','Active','Paused'],filter)}</select></div><div class="table-wrap"><table><thead><tr><th>Tool / Service</th><th>Website</th><th>Amount (USD)</th><th>Amount (LKR)</th><th>Renewal Date</th><th>Reminder</th><th>Auto-Renew</th><th>Status</th><th></th></tr></thead><tbody>${list.map((s,i)=>`<tr><td><div class="project-name">${faviconMarkup(s)}${esc(s.name)}</div></td><td><a href="https://${esc(s.website.replace(/^https?:\/\//,''))}" target="_blank" rel="noopener noreferrer">${esc(s.website)}</a></td><td>${money(s.amount,'USD')}</td><td>${money(s.amount*db.settings.fx,'LKR')}</td><td>${date(s.renewal)}</td><td>${s.reminder} days before</td><td><button class="switch ${s.auto?'on':''}" role="switch" aria-checked="${s.auto}" aria-label="Track auto-renew for ${esc(s.name)}" data-toggle-sub="${s.id}"></button></td><td>${badge(s.status)}</td><td><button class="iconbtn" data-edit="subscriptions:${s.id}" aria-label="Edit ${esc(s.name)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div><div class="grid equal">${panel('Upcoming Renewals','clock',active.sort((a,b)=>a.renewal.localeCompare(b.renewal)).slice(0,3).map(s=>`<div class="row">${faviconMarkup(s)}<div class="row-main"><b>${esc(s.name)}</b><small>${money(s.amount,'USD')} · ${date(s.renewal)}</small></div><button data-edit="subscriptions:${s.id}">Manage</button></div>`).join(''))}${panel('Reminder Center','bell',`<p class="section-note">Renewal reminders appear here while the app is open. Auto-renew tracks your preference; it does not change your provider’s billing.</p>${active.filter(s=>s.renewal<=offset(s.reminder)&&s.renewal>=today()).map(s=>`<div class="row"><span class="tile">${icon('bell')}</span><div class="row-main"><b>${esc(s.name)} renews soon</b><small>${date(s.renewal)} · ${money(s.amount,'USD')}</small></div></div>`).join('')||'<div class="empty">No reminders due yet.</div>'}`)}</div>`}
function expenseGradient(){const cats=[...new Set(db.transactions.filter(t=>t.type==='Expense').map(t=>t.category))],colors=['#ff7025','#e74d10','#ab491c','#777','#a6aba5'];let n=0;return expenses()?'conic-gradient('+cats.map((c,i)=>{let start=n;n+=db.transactions.filter(t=>t.type==='Expense'&&t.category===c).reduce((a,t)=>a+ +t.amount,0)/expenses()*100;return colors[i%colors.length]+' '+start+'% '+n+'%'}).join(',')+')':'#333'}
function finance(){const categories=[...new Set(db.transactions.filter(t=>t.type==='Expense').map(t=>t.category))];return hero('Finance','Track revenue, expenses, and studio performance.',addBtn('transactions','Add Transaction'))+`<div class="stats">${stat('Total Revenue',money(revenue()),'money','green')}${stat('Total Expenses',money(expenses()),'chart','red')}${stat('Net Profit',money(revenue()-expenses()),'trend','green')}${stat('Outstanding',money(outstanding()),'clock')}</div><div class="grid two">${panel('Revenue & Expenses','chart',chart(),rangeControl())}${panel('Expense Breakdown','finance',`<div class="health"><div class="ring" style="background:${expenseGradient()}"><div class="ring-inner"><strong style="font-size:20px">${money(expenses())}</strong><small>Total expenses</small></div></div><div class="health-list">${categories.map(c=>`<div><span>${esc(c)}</span><b>${expenses()?Math.round(db.transactions.filter(t=>t.type==='Expense'&&t.category===c).reduce((s,t)=>s+ +t.amount,0)/expenses()*100):0}%</b></div>`).join('')}</div></div>`)}</div><div class="grid">${panel('Transactions','bills',`<div class="table-wrap"><table><thead><tr><th>Description</th><th>Category</th><th>Date</th><th>Type</th><th>Amount</th><th></th></tr></thead><tbody>${[...db.transactions].sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<tr><td>${esc(t.title)}</td><td>${esc(t.category)}</td><td>${date(t.date)}</td><td>${badge(t.type)}</td><td style="color:${t.type==='Income'?'#26754e':'#a83b32'}">${t.type==='Income'?'+':'−'}${money(t.amount)}</td><td><button class="iconbtn" data-edit="transactions:${t.id}" aria-label="Edit ${esc(t.title)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div>`,`<button data-action="export-transactions">${icon('download')}CSV</button>`)}</div>`}
function bills(){return hero('Bills & Invoices','Professional invoices. Clear payment tracking.',`<button class="primary" data-action="new-invoice">${icon('plus')}Create Invoice</button>`)+`<div class="stats">${stat('Invoices',db.invoices.length,'bills')}${stat('Paid',money(db.invoices.filter(i=>i.status==='Paid').reduce((s,i)=>s+totalInvoice(i),0)),'tasks','green')}${stat('Outstanding',money(outstanding()),'clock','red')}${stat('Drafts',db.invoices.filter(i=>i.status==='Draft').length,'edit','blue')}</div><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Client</th><th>Issued</th><th>Due Date</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${db.invoices.map(i=>`<tr><td>${esc(i.number)}</td><td>${esc(i.client)}</td><td>${date(i.issued)}</td><td>${date(i.due)}</td><td>${money(totalInvoice(i))}</td><td><select aria-label="Status for invoice ${esc(i.number)}" data-invoice-status="${i.id}">${options(['Draft','Sent','Paid','Overdue'],i.status)}</select></td><td><button data-open-invoice="${i.id}">${icon('edit')}Open</button></td></tr>`).join('')}</tbody></table></div><p class="section-note">Invoice statuses are tracked locally. Sending and payment collection are managed outside this app.</p>`}
function invoiceEditor(){if(!invoice)invoice={id:id(),number:db.settings.prefix+new Date().getFullYear()+'-'+String(db.invoices.length+1).padStart(3,'0'),client:db.clients[0]?.name||'',issued:today(),due:offset(14),notes:'Thank you for your business!',status:'Draft',tax:+db.settings.tax,items:[{description:'Design services',qty:1,rate:0}]};return heading('Create Invoice','Build and save professional invoices for your clients.',`<div class="row-actions"><button data-action="save-invoice">Save Draft</button><button class="primary" data-action="print-invoice">${icon('download')}Download PDF</button></div>`)+`<div class="invoice-layout"><section class="panel invoice-editor"><div class="panel-head"><h2>Invoice Details</h2><button data-go="bills">Back to Bills</button></div><div class="form-grid">${field('Client',`<input data-invoice="client" list="client-names" value="${esc(invoice.client)}"><datalist id="client-names">${db.clients.map(c=>`<option value="${esc(c.name)}">`).join('')}</datalist>`)}${field('Invoice Number',`<input data-invoice="number" value="${esc(invoice.number)}">`)}${field('Issue Date',`<input type="date" data-invoice="issued" value="${invoice.issued}">`)}${field('Due Date',`<input type="date" data-invoice="due" value="${invoice.due}">`)}${field('Notes to Client',`<textarea data-invoice="notes">${esc(invoice.notes)}</textarea>`,'full')}${field('Tax (%)',`<input type="number" min="0" max="100" step="0.1" data-invoice="tax" value="${invoice.tax}">`)}</div><div class="panel-head"><h2>Invoice Items</h2><button data-action="add-invoice-item">${icon('plus')}Add Item</button></div><div class="invoice-item section-note"><span>Description</span><span>Qty</span><span>Rate</span></div><div id="invoice-items">${invoice.items.map((x,i)=>`<div class="invoice-item"><input aria-label="Item ${i+1} description" data-item="${i}:description" value="${esc(x.description)}"><input aria-label="Item ${i+1} quantity" type="number" min="0" step=".01" data-item="${i}:qty" value="${x.qty}"><input aria-label="Item ${i+1} rate" type="number" min="0" step=".01" data-item="${i}:rate" value="${x.rate}"><button data-remove-item="${i}" aria-label="Remove item ${i+1}">${icon('trash')}</button></div>`).join('')}</div><p class="section-note">Download PDF opens your browser’s print dialog. Choose “Save as PDF” for a clean invoice.</p></section><section id="invoice-paper" class="paper">${invoicePaper()}</section></div>`}
function invoicePaper(){const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:invoice.currency||db.settings.currency}).format(v||0);const subtotal=invoice.items.reduce((s,x)=>s+ +x.qty* +x.rate,0);return `<div class="paper-head"><div style="display:flex;gap:12px;align-items:center"><span class="logo">◕</span><div><h2>${esc(db.settings.brand)}</h2></div></div><h2 style="font-size:24px;color:#60636b">INVOICE</h2></div><div class="grid equal" style="margin-top:24px"><div><b>${esc(db.settings.studio)}</b><p>${esc(db.settings.address)}<br>${esc(db.settings.email)}</p></div><div style="text-align:right"><p>Invoice No: &nbsp; ${esc(invoice.number)}<br>Issue Date: &nbsp; ${date(invoice.issued)}<br>Due Date: &nbsp; ${date(invoice.due)}</p></div></div><h3>Bill To</h3><b>${esc(invoice.client)}</b><p>${esc(db.clients.find(c=>c.name===invoice.client)?.email||'')}</p><table><thead><tr><th>Description</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead><tbody>${invoice.items.map(x=>`<tr><td>${esc(x.description)}</td><td>${x.qty}</td><td>${money(x.rate)}</td><td>${money(x.qty*x.rate)}</td></tr>`).join('')}</tbody></table><div class="paper-total"><span>Subtotal</span><b>${money(subtotal)}</b><span>Tax (${invoice.tax}%)</span><b>${money(subtotal*invoice.tax/100)}</b><strong>Total</strong><strong>${money(totalInvoice(invoice))}</strong></div><div class="signature">${esc(db.settings.brand)}</div><p>${esc(invoice.notes||'Thank you for your business!')}</p>`}
function insights(){const overdue=db.tasks.filter(t=>t.due<today()&&t.status!=='Done');return heading('Insights','A clearer next step from your saved records.')+`<div class="grid equal">${panel('Cashflow over time','chart',chart(),rangeControl())}${panel('Next steps','tasks',(overdue.length?`<div class="row"><div class="row-main"><b>Review ${overdue.length} overdue tasks</b><small>Confirm dates and unblock delivery.</small></div>${navbutton('Tasks','tasks')}</div>`:'')+(outstanding()>0?`<div class="row"><div class="row-main"><b>Follow up on ${money(outstanding())}</b><small>Sent and overdue invoices.</small></div>${navbutton('Bills','bills')}</div>`:'')+(!overdue.length&&!outstanding()?'<div class="empty">No overdue tasks or outstanding issued invoices.</div>':''))}</div>`}
function users(){return hero('Your Team','The people behind the work.',addBtn('users','Add Member'))+`<div class="panel" style="margin-top:18px"><div class="panel-head"><h2>Team & Roles</h2><span class="badge">Profiles</span></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Email</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody>${db.users.map((u,i)=>`<tr><td><div class="project-name">${avatar(u.name,i)}${esc(u.name)}</div></td><td>${esc(u.email)}</td><td>${badge(u.role)}</td><td>${badge(u.status)}</td><td><button class="iconbtn" data-edit="users:${u.id}" aria-label="Edit ${esc(u.name)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div><p class="section-note">Manage profile details here. Enable individual account access in Team logins below.</p></div>`}
function baseRender(){if(page==='meetings'){page='home';history.replaceState(null,'','#home');toast('Meetings has been retired. Historical records remain in backups.')}if(page==='team')page='users';if(![...pages.map(p=>p.toLowerCase()),'invoice'].includes(page))page='home';$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="logo">◕</span><div><b>${esc(db.settings.brand)}</b><small>Studio OS</small></div></div><nav aria-label="Main navigation">${pages.map(p=>`<button data-go="${p.toLowerCase()}" class="${page===p.toLowerCase()||page==='invoice'&&p==='Bills'?'active':''}">${icon(p.toLowerCase())}${p==='Users'?'Team':p}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="primary" data-action="export">Back Up Workspace ${icon('download')}</button></div></aside><main class="workspace"><header class="topbar"><button class="mobile-menu iconbtn" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="searchbox global-search">${icon('search')}<input id="global-search" aria-label="Search workspace" placeholder="Search workspace…"><kbd>⌘ K</kbd><div class="search-results" id="search-results" hidden></div></div><div class="topright"><span class="date">${date(today())}</span><button class="iconbtn" data-action="notifications" aria-label="Notifications">${icon('bell')}</button><div class="profile">${avatar(db.settings.owner)}<div><b>${esc(db.settings.owner)}</b><small>Studio Owner</small></div></div></div></header><div id="page">${({home,projects,tasks,clients,subscriptions,finance,bills,invoice:invoiceEditor,insights,users,settings}[page])()}</div></main></div>`;bind();}
function options(values,current){return values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('')}
function field(label,input,cls=''){return `<label class="field ${cls}">${label}${input}</label>`}
const input=(name,value='',type='text',required=true,extra='')=>`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}>`;
const select=(name,values,value)=>`<select name="${name}">${options(values,value)}</select>`;
function projectSelect(current){return `<select name="project"><option value="">Studio / General</option>${db.projects.map(p=>`<option value="${p.id}" ${p.id===current?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`}
let modalTrigger=null;
function modal(title,content,sub=''){const d=$('#modal');if(!d.open)modalTrigger=document.activeElement;window.studioMotion?.cancel();d.innerHTML=`<div class="dialog-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div><button class="iconbtn" data-close aria-label="Close dialog">${icon('close')}</button></div>${content}`;d.querySelector('[data-close]').onclick=()=>d.close();if(!d.open)d.showModal();window.studioMotion?.enter(d,db.settings.motion,.2);d.onclose=()=>{window.studioMotion?.cancel();const trigger=modalTrigger;if(trigger?.isConnected)trigger.focus();else document.querySelector('#page button, #portal-account')?.focus();};}
function edit(kind,recordId,status){if(!['projects','tasks','clients','subscriptions','transactions','users'].includes(kind))return;const existing=db[kind]?.find(x=>x.id===recordId),x=existing||{},isEdit=!!existing;let fields='';if(kind==='projects')fields=field('Project Name',input('name',x.name))+field('Client',input('client',x.client))+field('Status',select('status',['Planning','In Progress','In Review','On Hold','Delivered','Portfolio Queue','Archived'],x.status||'Planning'))+field('Due Date',input('due',x.due||offset(14),'date'))+field('Budget',input('budget',x.budget||0,'number',true,'min="0" step=".01"'))+field('Owner',input('owner',x.owner||db.settings.owner.split(' ')[0]))+field('Description',`<textarea name="description">${esc(x.description)}</textarea>`,'full');
if(kind==='tasks')fields=field('Task Title',input('title',x.title),'full')+field('Project',projectSelect(x.project))+field('Status',select('status',['Backlog','In Progress','Review','Done'],x.status||status||'Backlog'))+field('Priority',select('priority',['Low','Medium','High'],x.priority||'Medium'))+field('Due Date',input('due',x.due||offset(3),'date'))+field('Assignee',input('assignee',x.assignee||db.settings.owner.split(' ')[0]))+field('Description',`<textarea name="description">${esc(x.description)}</textarea>`,'full');
if(kind==='clients')fields=field('Company Name',input('name',x.name))+field('Primary Contact',input('contact',x.contact))+field('Email',input('email',x.email,'email'))+field('Phone',input('phone',x.phone,'tel',false))+field('Website',input('website',x.website,'text',false))+field('Industry',input('industry',x.industry,'text',false))+field('Status',select('status',['Active','Inactive','Blacklisted'],x.status||'Active'))+field('Location',input('location',x.location||'Colombo, Sri Lanka','text',false))+field('Notes',`<textarea name="notes">${esc(x.notes)}</textarea>`,'full');
if(kind==='subscriptions')fields=field('Tool / Service',input('name',x.name))+field('Website',input('website',x.website,'text',false))+field('Monthly Cost (USD)',input('amount',x.amount||0,'number',true,'min="0" step=".01"'))+field('Renewal Date',input('renewal',x.renewal||offset(30),'date'))+field('Reminder (days before)',input('reminder',x.reminder??3,'number',true,'min="0" max="30"'))+field('Status',select('status',['Active','Paused'],x.status||'Active'))+field('Auto-Renew',select('auto',['On','Off'],x.auto===false?'Off':'On'));
if(kind==='transactions')fields=field('Description',input('title',x.title),'full')+field('Amount',input('amount',x.amount||0,'number',true,'min=".01" step=".01"'))+field('Type',select('type',['Income','Expense'],x.type||'Income'))+field('Date',input('date',x.date||today(),'date'))+field('Category',input('category',x.category||'Projects'));
if(kind==='users')fields=field('Full Name',input('name',x.name))+field('Email',input('email',x.email,'email'))+field('Role',select('role',['Founder','Manager','Member'],x.role||'Member'))+field('Status',select('status',['Active','Inactive'],x.status||'Active'));
const singular={projects:'Project',tasks:'Task',clients:'Client',subscriptions:'Subscription',transactions:'Transaction',users:'Team Member'}[kind];modal(`${isEdit?'Edit':'New'} ${singular}`,`<form id="record-form"><div class="form-grid">${fields}</div><div class="dialog-actions">${isEdit?`<button type="button" class="danger" id="delete-record">${icon('trash')}Delete</button>`:''}<button class="primary" type="submit">${icon('check')}Save ${singular}</button></div></form>`);
$('#record-form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));for(const k of ['progress','budget','amount','reminder'])if(k in values)values[k]=Number(values[k]);if('auto'in values)values.auto=values.auto==='On';if(kind==='clients'&&db.clients.some(c=>c.id!==x.id&&c.name.trim().toLowerCase()===values.name.trim().toLowerCase())){toast('A client with this company name already exists.');return}const updated={...x,...values,id:x.id||id()};if(typeof extendRecord==='function')extendRecord(kind,updated,e.target);if(kind==='clients'&&existing&&existing.name!==values.name){db.projects.forEach(p=>{if(p.client===existing.name)p.client=values.name});db.invoices.forEach(i=>{if(i.client===existing.name)i.client=values.name})}if(isEdit)db[kind]=db[kind].map(v=>v.id===x.id?updated:v);else db[kind].unshift(updated);save(`${singular} ${isEdit?'updated':'created'}: ${values.name||values.title}`);$('#modal').close();render()};if(isEdit)$('#delete-record').onclick=()=>{modal('Delete '+singular+'?',`<p class="section-note">This removes “${esc(x.name||x.title)}” from this workspace. Linked records will remain.</p><div class="dialog-actions"><button id="confirm-delete" class="danger">Delete ${singular}</button></div>`);$('#confirm-delete').onclick=()=>{db[kind]=db[kind].filter(v=>v.id!==x.id);if(kind==='projects'){db.tasks.forEach(t=>{if(t.project===x.id)t.project=''})}save(singular+' deleted');$('#modal').close();render()}}}
function download(name,text,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function saveInvoice(){if(!invoice.client.trim()||!invoice.number.trim()||!invoice.issued||!invoice.due){toast('Add a client, invoice number, and dates.');return false}if(db.invoices.some(i=>i.id!==invoice.id&&i.number===invoice.number)){toast('Invoice number already exists. Choose a unique number.');return false}if(!invoice.items.length||invoice.items.some(x=>!x.description.trim()||!Number.isFinite(x.qty)||!Number.isFinite(x.rate)||!Number.isFinite(x.qty*x.rate)||x.qty<=0||x.rate<0)||!Number.isFinite(invoice.tax)||!Number.isFinite(totalInvoice(invoice))||invoice.tax<0||invoice.tax>100){toast('Add valid invoice items and a tax rate from 0 to 100.');return false}invoice.currency=invoice.currency||db.settings.currency;const exists=db.invoices.some(i=>i.id===invoice.id);if(exists)db.invoices=db.invoices.map(i=>i.id===invoice.id?structuredClone(invoice):i);else db.invoices.unshift(structuredClone(invoice));save('Invoice saved: '+invoice.number);return true}
function action(a){if(a==='menu')$('.sidebar').classList.toggle('open');if(a==='export')download('chakra-backup-'+today()+'.json',JSON.stringify(db,null,2));if(a==='import')$('#import-file').click();if(a==='notifications'){const old=$('.notification-menu');if(old){old.remove();return}const div=document.createElement('div');div.className='notification-menu';div.innerHTML=`<strong>Workspace Reminders</strong><p>${db.tasks.filter(t=>t.due<=today()&&t.status!=='Done').length} unfinished tasks due today or earlier.</p><p>${db.subscriptions.filter(s=>s.status==='Active'&&s.renewal<=offset(s.reminder)&&s.renewal>=today()).length} subscription renewal reminders.</p><p class="section-note">Checked when you open the app.</p>`;$('.topbar').append(div)}if(a==='new-invoice'){invoice={id:id(),number:db.settings.prefix+new Date().getFullYear()+'-'+String(db.invoices.length+1).padStart(3,'0'),client:db.clients[0]?.name||'',project:'',issued:today(),due:offset(14),notes:'Thank you for your business!',status:'Draft',tax:+db.settings.tax,items:[{description:'Design services',qty:1,rate:0}]};go('invoice')}if(a==='save-invoice')saveInvoice();if(a==='print-invoice'){if(saveInvoice())window.print()}if(a==='add-invoice-item'){invoice.items.push({description:'',qty:1,rate:0});render()}if(a==='export-transactions'){const cell=s=>'"'+String(s).replace(/"/g,'""')+'"';download('chakra-transactions.csv',[['Description','Type','Category','Date','Amount','Currency'],...db.transactions.map(t=>[t.title,t.type,t.category,t.date,t.amount,db.settings.currency])].map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv')}if(a==='clear-demo'||a==='reset-demo'){modal(a==='clear-demo'?'Clear workspace records?':'Restore sample workspace?',`<p class="section-note">This replaces your current records. Export a backup first if you want to keep them.</p><div class="dialog-actions"><button id="export-before-reset">Export Backup</button><button id="confirm-reset" class="danger">${a==='clear-demo'?'Clear Records':'Restore Demo'}</button></div>`);$('#export-before-reset').onclick=()=>action('export');$('#confirm-reset').onclick=()=>{let settings={...db.settings},legacyMeetings=structuredClone(db.meetings);db=structuredClone(seed);if(a==='clear-demo')for(const k of ['projects','tasks','clients','subscriptions','meetings','transactions','invoices','activity'])db[k]=[];db.meetings=legacyMeetings;db.settings=settings;save('Workspace '+(a==='clear-demo'?'cleared':'restored'));$('#modal').close();render()}}}
function bind(){$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$$('[data-add]').forEach(b=>b.onclick=()=>edit(b.dataset.add,null,b.dataset.status));$$('[data-edit]').forEach(b=>b.onclick=()=>edit(...b.dataset.edit.split(':')));$$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$$('[data-client]').forEach(b=>b.onclick=()=>{clientSelected=b.dataset.client;render()});$$('[data-client]').forEach(b=>b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.click()}});$$('[data-settings-tab]').forEach(b=>b.onclick=()=>{settingsTab=b.dataset.settingsTab;render()});$$('[data-toggle-sub]').forEach(b=>b.onclick=()=>{const s=db.subscriptions.find(x=>x.id===b.dataset.toggleSub);s.auto=!s.auto;save('Auto-renew tracking updated');render()});$$('[data-task-status]').forEach(b=>b.onchange=()=>moveTask(b.dataset.taskStatus,b.value));$$('[data-task]').forEach(b=>b.ondragstart=e=>{e.dataTransfer.setData('text/plain',b.dataset.task);e.dataTransfer.effectAllowed='move'});$$('[data-drop]').forEach(b=>{b.ondragover=e=>{e.preventDefault();b.classList.add('dragover')};b.ondragleave=()=>b.classList.remove('dragover');b.ondrop=e=>{e.preventDefault();moveTask(e.dataTransfer.getData('text/plain'),b.dataset.drop)}});$$('[data-open-invoice]').forEach(b=>b.onclick=()=>{invoice=structuredClone(db.invoices.find(i=>i.id===b.dataset.openInvoice));go('invoice')});$$('[data-invoice-status]').forEach(b=>b.onchange=()=>{db.invoices.find(i=>i.id===b.dataset.invoiceStatus).status=b.value;save('Invoice status updated');render()});$$('[data-invoice]').forEach(b=>b.oninput=()=>{invoice[b.dataset.invoice]=b.dataset.invoice==='tax'?+b.value:b.value;$('#invoice-paper').innerHTML=invoicePaper()});$$('[data-item]').forEach(b=>b.oninput=()=>{let [i,k]=b.dataset.item.split(':');invoice.items[+i][k]=k==='description'?b.value:+b.value;$('#invoice-paper').innerHTML=invoicePaper()});$$('[data-remove-item]').forEach(b=>b.onclick=()=>{invoice.items.splice(+b.dataset.removeItem,1);render()});if($('#page-search'))$('#page-search').oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;render();$('#page-search').focus();$('#page-search').setSelectionRange(pos,pos)};if($('#status-filter'))$('#status-filter').onchange=e=>{filter=e.target.value;render()};if($('#finance-period'))$('#finance-period').onchange=e=>{financePeriod=e.target.value;render()};if($('#project-sort'))$('#project-sort').onchange=e=>{let list=[...db.projects].filter(p=>(filter==='All'||filter==='Active'&&!['Delivered','Archived','Portfolio Queue','On Hold'].includes(p.status)||p.status===filter)&&(!query||(p.name+' '+p.client).toLowerCase().includes(query.toLowerCase())));if(e.target.value==='date')list.sort((a,b)=>a.due.localeCompare(b.due));if(e.target.value==='name')list.sort((a,b)=>a.name.localeCompare(b.name));$('#project-rows').innerHTML=projectRows(list);$$('#project-rows [data-edit]').forEach(b=>b.onclick=()=>edit(...b.dataset.edit.split(':')))};for(const f of ['settings-form','invoice-settings'])if($('#'+f))$('#'+f).onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));for(const k of ['tax','fx','target'])if(k in v)v[k]=+v[k];db.settings={...db.settings,...v};save('Workspace settings saved');render()};$('#global-search').oninput=e=>{const q=e.target.value.trim().toLowerCase(),box=$('#search-results');if(!q){box.hidden=true;return}const results=['projects','tasks','clients'].flatMap(k=>db[k].filter(x=>(x.name||x.title).toLowerCase().includes(q)).map(x=>({kind:k,x}))).slice(0,8);box.hidden=false;box.innerHTML=results.map(r=>`<button data-result="${r.kind}:${r.x.id}"><span>${esc(r.x.name||r.x.title)}</span><small class="muted">${r.kind}</small></button>`).join('')||'<p class="section-note">No matching records</p>';$$('[data-result]').forEach(b=>b.onclick=()=>{box.hidden=true;edit(...b.dataset.result.split(':'))})};}
function moveTask(taskId,status){const t=db.tasks.find(t=>t.id===taskId);if(!t)return;t.status=status;if(status==='Done'){t.progress=100;if(t.checklist)t.checklist=t.checklist.map(c=>({...c,done:true}));}save('Task moved to '+status);render()}
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const incoming=JSON.parse(await file.text());if(!validDB(incoming))throw Error('Not a valid Chakra Studio OS backup.');modal('Replace this workspace?',`<p class="section-note">Import ${incoming.projects.length} projects, ${incoming.tasks.length} tasks, and ${incoming.clients.length} clients from ${esc(file.name)}? This replaces your current records.</p><div class="dialog-actions"><button id="backup-first">Export Current</button><button class="primary" id="confirm-import">Import Backup</button></div>`);$('#backup-first').onclick=()=>action('export');$('#confirm-import').onclick=()=>{db=incoming;save('Workspace backup imported');$('#modal').close();invoice=structuredClone(db.invoices[0]);render()}}catch(err){toast('Import failed: '+err.message)}e.target.value=''};
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#global-search').focus()}if(e.key==='Escape'){$('.sidebar')?.classList.remove('open');$('.notification-menu')?.remove();if($('#search-results'))$('#search-results').hidden=true}});document.addEventListener('click',e=>{if(!e.target.closest('.global-search')&&$('#search-results'))$('#search-results').hidden=true});
